export type ParsedWithdrawLeftoverInstruction<
  TProgram extends string = typeof DYNAMIC_BONDING_CURVE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    poolAuthority: TAccountMetas[0];
    config: TAccountMetas[1];
    virtualPool: TAccountMetas[2];
    /** The receiver token account, withdraw to ATA */
    tokenBaseAccount: TAccountMetas[3];
    /** The vault token account for output token */
    baseVault: TAccountMetas[4];
    /** The mint of quote token */
    baseMint: TAccountMetas[5];
    leftoverReceiver: TAccountMetas[6];
    /** Token base program */
    tokenBaseProgram: TAccountMetas[7];
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: WithdrawLeftoverInstructionData;
};

export function parseWithdrawLeftoverInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedWithdrawLeftoverInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      poolAuthority: getNextAccount(),
      config: getNextAccount(),
      virtualPool: getNextAccount(),
      tokenBaseAccount: getNextAccount(),
      baseVault: getNextAccount(),
      baseMint: getNextAccount(),
      leftoverReceiver: getNextAccount(),
      tokenBaseProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getWithdrawLeftoverInstructionDataDecoder().decode(instruction.data),
  };
}
